document.querySelector('#supportForm').addEventListener('submit',async event=>{event.preventDefault();const button=document.querySelector('#supportButton'),output=document.querySelector('#supportResult');button.disabled=true;output.textContent='Gönderiliyor…';try{const response=await fetch('/api/support',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:document.querySelector('#supportName').value,email:document.querySelector('#supportEmail').value,category:document.querySelector('#supportCategory').value,message:document.querySelector('#supportMessage').value})}),data=await response.json();if(!response.ok)throw new Error(data.error||'Talep gönderilemedi');output.textContent=`Talebiniz kaydedildi · ${data.id.slice(0,8)}`;event.target.reset()}catch(error){output.textContent=error.message}finally{button.disabled=false}});
